def solve():
    solutions = []
    for c in range(1, 15):
        target = 6**c - 1
        for b in range(1, 30):
            val_b = 3**b
            if val_b >= target:
                break
            val_a = target - val_b
            if val_a > 0 and (val_a & (val_a - 1)) == 0:
                a = val_a.bit_length() - 1
                solutions.append((a, b, c))
    return solutions

solutions = solve()
