def find_solutions(max_c):
    solutions = []
    for c in range(1, max_c + 1):
        target = 6**c - 1
        for a in range(1, 20):
            pow2 = 2**a
            if pow2 >= target:
                break
            if (target - pow2) % 3 == 0:
                diff = target - pow2
                b = 0
                temp_diff = diff
                while temp_diff > 1 and temp_diff % 3 == 0:
                    temp_diff //= 3
                    b += 1
                if temp_diff == 1 and b > 0:
                    B = 2**a + 1
                    T = 3**b + 1
                    S = 6**c + 1
                    solutions.append((B, T, S))
    return solutions

print(find_solutions(10))

def find_solutions_final(max_c):
