    for c in range(1, max_c + 1):
        target = 6**c - 1
        for b in range(1, 100):
            pow3 = 3**b
            if pow3 >= target:
                break
            diff = target - pow3
            if diff > 1 and (diff & (diff - 1)) == 0:
                a = diff.bit_length() - 1
                if 2**a == diff:
                    B = 2**a + 1
                    T = 3**b + 1
                    S = 6**c + 1
                    solutions.append((B, T, S))
    return sorted(solutions)

